// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadOswald = makeLoadFont('Oswald');

// Library: none — native interpolate/spring

// Module-level font loading guaranteed before frame 0
const { fontFamily: interFamily } = loadInter();
const { fontFamily: oswaldFamily } = loadOswald();



export type InfographicProps = Record<string, any>;

const Infographic: React.FC<InfographicProps> = ({
  backgroundColor = "#0f1c3f",
  transparentBackground = false,
  primaryColor = "#62c4a7",
  secondaryColor = "#eeebe3",
  textColor = "#ffffff",
  percentage = 11,
  textLine1 = "OF MILLENNIALS",
  textLine2 = "SAY THEIR",
  textLine3 = "FINANCIAL WELLNESS",
  textLine4 = "IS HEALTHY",
  durationInSeconds = 8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Responsive scale factor based on 1080p canvas
  const s = Math.min(width, height) / 1080; 

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout parameters
  const chartCenterX = width * 0.28;
  const textStartX = width * 0.52;
  const radius = 330 * s;
  const strokeWidth = 140 * s;
  const circumference = 2 * Math.PI * radius;

  // Animation values
  const bgScale = spring({ frame, fps, config: { damping: 14, stiffness: 100 } });
  
  // The slice starts growing at frame 15
  const progressSpring = spring({ frame: frame - 15, fps, config: { damping: 16 } });
  const drawProgress = Math.max(0, progressSpring * (percentage / 100));
  const dashoffset = circumference - (circumference * drawProgress);

  // Icon entrance
  const iconScale = spring({ frame: frame - 20, fps, config: { damping: 12, mass: 0.8 } });
  const iconOp = interpolate(frame, [20, 30], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  // Big number entrance
  const percentVal = Math.round(interpolate(frame, [15, 45], [0, percentage], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }));
  const percentY = interpolate(frame, [15, 30], [50 * s, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const percentOp = interpolate(frame, [15, 30], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  // Staggered text lines
  const textLines = [
    { text: textLine1, color: textColor, delay: 30 },
    { text: textLine2, color: textColor, delay: 35 },
    { text: textLine3, color: primaryColor, delay: 40 },
    { text: textLine4, color: primaryColor, delay: 45 },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Donut Chart Container */}
      <div style={{
        position: 'absolute',
        left: chartCenterX,
        top: height * 0.5,
        transform: 'translate(-50%, -50%)',
        width: 800 * s,
        height: 800 * s,
      }}>
        {/* SVG Ring Graphics */}
        <svg 
          width="100%" 
          height="100%" 
          viewBox="-400 -400 800 800" 
          style={{ overflow: 'visible', position: 'absolute' }}
        >
          <g transform="rotate(-90)" style={{ transition: 'none' }}>
            {/* Background Donut */}
            <circle
              r={radius}
              fill="none"
              stroke={secondaryColor}
              strokeWidth={strokeWidth}
              style={{
                transform: `scale(${bgScale})`,
                opacity: bgScale > 0.01 ? 1 : 0,
                transition: 'none',
              }}
            />
            {/* Value Slice Donut */}
            <circle
              r={radius}
              fill="none"
              stroke={primaryColor}
              strokeWidth={strokeWidth}
              strokeDasharray={circumference}
              strokeDashoffset={dashoffset}
              strokeLinecap="butt"
              style={{
                opacity: drawProgress > 0.001 ? 1 : 0,
                transition: 'none',
              }}
            />
          </g>
        </svg>

        {/* Center Icons (Person & Heart) */}
        <div style={{
          position: 'absolute',
          left: '50%',
          top: '50%',
          transform: `translate(-50%, -50%) scale(${iconScale})`,
          opacity: iconOp,
          width: 220 * s,
          height: 220 * s,
          transition: 'none',
        }}>
          {/* Person SVG */}
          <svg width="100%" height="100%" viewBox="0 0 24 24" fill="none" stroke={primaryColor} strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
            <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
            <circle cx="12" cy="7" r="4" />
          </svg>
          {/* Overlapping Heart SVG */}
          <svg 
            style={{ position: 'absolute', bottom: -5 * s, right: -15 * s }} 
            width={100 * s} 
            height={100 * s} 
            viewBox="0 0 24 24" 
            fill={primaryColor} 
            stroke={backgroundColor} 
            strokeWidth={2.5}
            strokeLinejoin="round"
          >
            <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/>
          </svg>
        </div>
      </div>

      {/* Typography Layout */}
      <div style={{
        position: 'absolute',
        left: textStartX,
        top: '50%',
        transform: 'translateY(-50%)',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        alignItems: 'flex-start',
      }}>
        
        {/* Animated Percentage Text */}
        <div style={{
          fontSize: 340 * s,
          fontWeight: 700,
          color: primaryColor,
          lineHeight: 0.9,
          fontFamily: oswaldFamily,
          letterSpacing: '-0.02em',
          marginBottom: 10 * s,
          transform: `translateY(${percentY}px)`,
          opacity: percentOp,
          transition: 'none',
        }}>
          {percentVal}%
        </div>

        {/* Staggered Subtitles */}
        {textLines.map((item, i) => {
          // Calculate stagger animation for each line
          const lineY = interpolate(frame - item.delay, [0, 15], [30 * s, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
          const lineOp = interpolate(frame - item.delay, [0, 15], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

          return (
            <div 
              key={i} 
              style={{ 
                fontSize: 75 * s, 
                fontWeight: 900, 
                color: item.color, 
                lineHeight: 1.1, 
                fontFamily: interFamily,
                textTransform: 'uppercase',
                letterSpacing: '-0.02em',
                transform: `translateY(${lineY}px)`,
                opacity: lineOp,
                transition: 'none',
              }}
            >
              {item.text}
            </div>
          );
        })}
      </div>

    </AbsoluteFill>
  );
};

export default Infographic;